        fa: "«Pet» عمدتاً برای خطاب کودکان به کار می‌رود. توجه کنید که سه واژه‌ی آخرِ فهرست محدود به خطابِ افرادی که واقعاً دوستشان داریم نیست. برای مثال، چندان غیرعادی نیست که مأمور اتوبوس در لندن هر دختر یا زنی را «love» صدا بزند. (همتای او در گلاسکو مسافران زن را «hen» می‌نامد.) اما برای تو بهتر است چنین واژه‌هایی را برای کسانی نگه داری که رابطه‌ی نزدیکی با آن‌ها داری!"
