          answerFa: "فعل: آگاه شدن، –، هدف، شکست خوردن، مشکل | اسم: آگاهی، مشکل، هدف، شکست، مشکل | صفت: قابل دستیابی، دشوار، هدفمند، شکست خورده/شکستن، نگران‌کننده/آزاردهنده/آسیب‌دیده. نظرات: هدفمند در جملاتی مانند 'دولت تصمیم گرفته بود بودجه اضافی را به گروه‌های هدفمند در جامعه اختصاص دهد' استفاده می‌شود (به طور خاص انتخاب شده)؛ دشوار فعل قیدی در انگلیسی ندارد؛ ما می‌گوییم 'ما با دشواری آن را انجام دادیم.'؛ نگران‌کننده: ما اخیراً شاهد توسعه‌های بسیار نگران‌کننده‌ای بوده‌ایم. (نگران‌کننده)؛ آزاردهنده: آن‌ها یک گروه دانش‌آموزان آزاردهنده هستند. (مشکل‌ساز)؛ آسیب‌دیده: اخیراً در مورد دخترم احساس آسیب‌دیدگی کرده‌ام. (نگران)"
